Get-ChildItem "HKLM:\SOFTWARE\ESET\ESET Security" -ErrorAction SilentlyContinue -Recurse -Depth 4 | ForEach-Object { $p = Get-ItemProperty $_.PSPath -ErrorAction SilentlyContinue; if ($p) { $h = $p.PSObject.Properties | Where-Object { $_.Name -match "SSL|Tls|Filter|Ssl|Filt|SslFilter|SslTls|SslTlsFiltering|SslConfig|SslSettings|Filtering|Exclude|Exclusion|Network|Inspect" }; if ($h) { Write-Host "FOUND:" $_.Name -ForegroundColor Yellow; $h | Format-Table Name,Value -AutoSize } } }; Write-Host "---SCAN DONE---"
